import{z as o,x as l,o as B,c as s,q as e,j as r,D as a,d as t,s as i,S as n}from"./chunks/framework.C8m1ZpeB.js";const _=JSON.parse('{"title":"暗池执行","description":"","frontmatter":{"title":"暗池执行","date":"2026-09-18T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/ex-dark-execution.md","filePath":"quant/ex-dark-execution.md","lastUpdated":1791063341000}'),d={name:"quant/ex-dark-execution.md"};function p(D,E,C,u,h,c){const A=l("Mermaid");return B(),s("div",null,[E[2]||(E[2]=e('<h1 id="暗池执行" tabindex="-1">暗池执行 <a class="header-anchor" href="#暗池执行" aria-label="Permalink to &quot;暗池执行&quot;">​</a></h1><div class="epigraph"><p>暗处的成交省下展示的脚印，代价是把成交时机交给别人定价：填成概率与事后漂移是暗腿的两个传感器，缺一个，暗池只是信仰。</p><footer>—— 据 Zhu, Do Dark Pools Harm Price Discovery?, Review of Financial Studies, 2014；Buti, Rindi and Werner 对暗池流动性的研究整理</footer></div><p><a href="/quant/ex-slice-scheduling-deep">上一课</a>把调度写成闭环控制，但状态变量全部来自明簿。主干 <a href="/quant/dark-pool-midpoint">暗池、ATS 与中点单</a>讲了匹配协议，<a href="/quant/dark-pool-routing">暗池路由</a>讲了分多少比例去暗处；本课深入执行端的暗腿工程：中点单怎么挂、填成怎么预测、毒性怎么按场所测、何时撤。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>暗腿与明腿的误差结构不同。明簿的失败模式是「付了价差才成交」，结果立即可见；暗池的失败模式是「没成交」或「成交即被逆向选择」：中点单只在公开对侧报价被吃掉时成交，成交事件与对手方的信息优势相关——你买到的，常是明市即将上涨前卖给你的人。同一份暗池份额于是呈现两种极端：长期不填，机会成本累积；或填得又快又准，事后中点漂移把价差节省吃光。问题是怎么把两种结局分开度量、分别定价。</p>',5)),(B(),r(n,null,{default:a(()=>[i(A,{id:"mermaid-13",class:"mermaid",graph:"flowchart%20TD%0A%20%20ORD%5B%22%E5%90%8C%E4%B8%80%E4%BB%BD%E6%9A%97%E6%B1%A0%E4%BB%BD%E9%A2%9D%E6%8C%82%E5%87%BA%22%5D%20--%3E%20A%5B%22%E7%BB%93%E5%B1%80%E4%B8%80%EF%BC%9A%E9%95%BF%E6%9C%9F%E4%B8%8D%E5%A1%AB%22%5D%0A%20%20ORD%20--%3E%20B%5B%22%E7%BB%93%E5%B1%80%E4%BA%8C%EF%BC%9A%E5%A1%AB%E5%BE%97%E5%8F%88%E5%BF%AB%E5%8F%88%E5%87%86%22%5D%0A%20%20A%20--%3E%20A1%5B%22%E6%9C%BA%E4%BC%9A%E6%88%90%E6%9C%AC%E7%B4%AF%E7%A7%AF%EF%BC%9A%E4%BB%B7%E6%A0%BC%E8%B5%B0%E6%8E%89%22%5D%0A%20%20B%20--%3E%20B1%5B%22%E4%BA%8B%E5%90%8E%E4%B8%AD%E7%82%B9%E6%BC%82%E7%A7%BB%E4%B8%8D%E5%88%A9%EF%BC%9A%E7%9C%81%E7%9A%84%E4%BB%B7%E5%B7%AE%E8%A2%AB%E9%80%86%E5%90%91%E9%80%89%E6%8B%A9%E5%90%83%E5%85%89%22%5D%0A%20%20LIT%5B%22%E5%AF%B9%E7%85%A7%EF%BC%9A%E6%98%8E%E7%B0%BF%E5%90%83%E5%8D%95%22%5D%20--%3E%20C%5B%22%E5%A4%B1%E8%B4%A5%E6%A8%A1%E5%BC%8F%E5%8D%95%E4%B8%80%EF%BC%9A%E4%BB%98%E4%BA%86%E4%BB%B7%E5%B7%AE%E6%89%8D%E6%88%90%E4%BA%A4%22%5D%0A%20%20C%20--%3E%20C1%5B%22%E7%BB%93%E6%9E%9C%E7%AB%8B%E5%8D%B3%E5%8F%AF%E8%A7%81%EF%BC%8C%E6%98%93%E4%BA%8E%E5%BA%A6%E9%87%8F%22%5D%0A%20%20A1%20--%3E%20D%5B%22%E7%BB%93%E8%AE%BA%EF%BC%9A%E4%B8%A4%E7%A7%8D%E7%BB%93%E5%B1%80%E5%88%86%E5%BC%80%E5%BA%A6%E9%87%8F%E3%80%81%E5%88%86%E5%88%AB%E5%AE%9A%E4%BB%B7%22%5D%0A%20%20B1%20--%3E%20D%0A"})]),fallback:a(()=>[...E[0]||(E[0]=[t(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=e('<p>中点单还有一层时变性：它锚在公开 BBO 上，价差每一跳、每次刷新都在改写你的实际挂价与队列位置。挂出去不动，不等于价格不动。</p><p><span class="marginnote">「中点单」翻译成小白话：把单子藏起来，价格定成公开市场买一卖一的正中间，不展示在任何人可见的盘口上，等对面有人愿意按这个价成交时再匿名配对。好处是不暴露意图、省半个价差；代价是只能等，而且不知道谁在跟你成交。</span></p><h3 id="暗腿的规格维度" tabindex="-1">暗腿的规格维度 <a class="header-anchor" href="#暗腿的规格维度" aria-label="Permalink to &quot;暗腿的规格维度&quot;">​</a></h3><p>单型：中点 peg、对侧最优 peg、参考价改善；可加最小数量与有效期。条件性：IOC 条件单在多场所同时试探、任一处成交即撤其余，用即时性换暴露时间。撤单策略：peg 需跟随 BBO 重挂，跟随延迟就是过期报价窗口。配额：场所级上限与轮换，见 <a href="/quant/dark-pool-routing">暗池路由</a> 的质量表。</p><p><span class="marginnote">暗池填成概率不是场所常数，而是明簿状态的函数：价差收窄、买盘堆积时，对侧被吃的概率与你的逆向选择概率同升。把暗池成交率当成场所固有的「流动性评分」，会在体制切换时选错场所。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>两个传感器，一个控制器。传感器一，条件填成率：对每个场所估计 hazard——给定明簿事件（价差触及、对侧挂量消耗、不平衡），暗单成交的条件概率，方法与 <a href="/quant/fill-probability">成交概率</a> 同族，事件来自对侧明簿。传感器二，事后漂移：成交后 1 分钟、5 分钟的中点相对成交价的运动，买入后下跌说明省下的价差被逆向选择吃掉；这是 <a href="/quant/effective-realized-spread">有效价差与实现价差</a> 在单场所上的应用。</p><p>控制器：暗腿份额由两个传感器在线修正——填成率低于基准且漂移为正，提高份额；漂移为负，压份额、缩有效期、加最小数量门槛。波动升高或临近事件时，无条件挂单的暴露时间变贵，改用 IOC 条件单或回明簿。阈值进规格文档，与 <a href="/quant/slippage-attribution">滑点归因</a> 的场所科目对齐。</p><p><span class="marginnote">常见误区：按历史成交率给暗池排名。填成率是明簿状态的函数：平静日价差窄、暗池填得多；恐慌日对手撤回明簿，暗池先干涸。排名靠前的场所在你最需要流动性的时候恰恰最不可靠，应按「条件于当日状态」的 hazard 动态分配，而不是按场所固定评分。</span></p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>中点协议的经济：省半价差、零展示，付出等待与柠檬折价。Zhu 的模型指出知情者偏好暗处，暗池份额上升会侵蚀价格发现；对执行者的含义是柠檬折价随份额与信息事件密度上升，常数折价假设失效。条件单改变期权结构：无条件中点单相当于送给对手方一份「按你方向成交」的期权；IOC 加最小数量抬高行权门槛，用暴露时间换信息保护。探测（对手方在明簿交替挂撤以试探暗池存量）之所以有效，正因为无条件 peg 存在；防御靠随机化尺寸、最小数量与条件标记，而不是反向对敲——后者越过红线。</p><p><span class="marginnote">「无条件挂单等于送出方向性期权」可以类比：在旧货市场挂一块「愿按均价整批收购」的牌子——只有认为自己手里的货不值这个价的人才来找你，知情交易者正是这样挑暗池下单的。IOC 加最小数量相当于把牌子改成「整批才收、限时有效」，把捡漏者挡在门外。</span></p><p>暗腿与调度层的接口：暗池成交的打印延迟使 <a href="/quant/ex-slice-scheduling-deep">进度误差</a> 被低估；控制器应把暗腿在途量单独建账。</p>',13)),(B(),r(n,null,{default:a(()=>[i(A,{id:"mermaid-53",class:"mermaid",graph:"flowchart%20TD%0A%20%20Q%5B%22%E6%AF%8D%E5%8D%95%E6%9A%97%E8%85%BF%E9%85%8D%E9%A2%9D%22%5D%20--%3E%20PEG%5B%22%E4%B8%AD%E7%82%B9%20peg%20%2F%20%E6%9D%A1%E4%BB%B6%E5%8D%95%22%5D%0A%20%20LIT%5B%22%E6%98%8E%E7%B0%BF%20BBO%20%E4%BA%8B%E4%BB%B6%E6%B5%81%22%5D%20--%3E%20HZ%5B%22%E6%9D%A1%E4%BB%B6%E5%A1%AB%E6%88%90%E7%8E%87%20hazard%22%5D%0A%20%20PEG%20--%3E%20FILL%5B%22%E6%9A%97%E6%B1%A0%E6%88%90%E4%BA%A4%E4%B8%8E%E6%89%93%E5%8D%B0%22%5D%0A%20%20FILL%20--%3E%20DR%5B%22%E4%BA%8B%E5%90%8E%E6%BC%82%E7%A7%BB%3A%201m%20%2F%205m%20%E4%B8%AD%E7%82%B9%22%5D%0A%20%20FILL%20--%3E%20PEG%0A%20%20HZ%20--%3E%20CTRL%7B%22%E6%8E%A7%E5%88%B6%E5%99%A8%22%7D%0A%20%20DR%20--%3E%20CTRL%0A%20%20CTRL%20--%3E%7C%E5%A1%AB%E6%88%90%E4%BD%8E%E4%B8%94%E6%BC%82%E7%A7%BB%E6%AD%A3%7C%20UP%5B%22%E6%8F%90%E9%AB%98%E4%BB%BD%E9%A2%9D%20%2F%20%E6%94%BE%E5%AE%BD%E6%9C%9F%E9%99%90%22%5D%0A%20%20CTRL%20--%3E%7C%E6%BC%82%E7%A7%BB%E8%B4%9F%7C%20DOWN%5B%22%E5%8E%8B%E4%BB%BD%E9%A2%9D%20%2F%20%E5%8A%A0%E6%9C%80%E5%B0%8F%E6%95%B0%E9%87%8F%20%2F%20IOC%22%5D%0A%20%20CTRL%20--%3E%20CAP%5B%22%E5%9C%BA%E6%89%80%E4%B8%8A%E9%99%90%E4%B8%8E%E8%BD%AE%E6%8D%A2%22%5D%0A"})]),fallback:a(()=>[...E[1]||(E[1]=[t(" Loading... ",-1)])]),_:1})),E[4]||(E[4]=e('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>A 股没有美股式 ATS：对应的大宗交易与盘后固定价格交易在时段、价格限制与披露上都不同，参数不可翻译。暗池数据自报、打印滞后，场所间比较必须同时窗口化。份额过高会反噬中点锚本身——公开簿变薄，锚的质量下降，见 <a href="/quant/dark-pool-midpoint">暗池、ATS 与中点单</a>。最优执行义务要求暗腿规则可解释：为什么此处、为何此时、省了多少，答不出就退回明簿。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>暗腿的两个传感器是条件填成率与事后漂移；只看成交率会选错场所。</li><li>中点单锚在 BBO 上，peg 跟随延迟就是过期报价窗口。</li><li>无条件挂单等于送出方向性期权；IOC 与最小数量用暴露时间换保护。</li><li>暗池折价随份额与信息事件密度上升，常数折价假设失效。</li><li>暗腿打印延迟会低估调度进度，须单独建账保守计入。</li><li>A 股无 ATS，对应机制是大宗与盘后固定价格，参数不可翻译。</li><li>出处：Zhu, <em>RFS</em>, 2014；Buti, Rindi and Werner 的暗池研究；价差口径见 Hasbrouck 的微观结构计量。</li></ul>',4))])}const m=o(d,[["render",p]]);export{_ as __pageData,m as default};
